#!/usr/bin/env node
// Renders spec/builtins.json — the authored builtin manifest — into every host
// and into docs/BUILTINS.md.
//
//     node tools/gen-builtins.mjs            write the generated files
//     node tools/gen-builtins.mjs --check    validate and diff, write nothing
//
// The renderings ARE committed, like the SQL map (tools/gen-sql-map.mjs): a
// PHP, Python, C++ or Lisp consumer must never need Node. Each host reads its
// rendering at startup as a native table — no JSON, no reflection — and its
// `define` refuses a builtin whose min/max/lazy/binds disagree with it, takes
// the extra arity rule from it, and refuses to finish registration with a
// manifest name it never defined. Staleness is caught by --check, which
// tools/check-generated.sh runs from tools/check.sh.
//
// Everything spec/builtins.md promises about the format is enforced here, so
// no host has to defend against a malformed manifest. A validation failure is
// a non-zero exit naming the entry and the key.

import { readFileSync, writeFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { dirname, resolve } from 'node:path';

const ROOT = resolve(dirname(fileURLToPath(import.meta.url)), '..');
const SOURCE = 'spec/builtins.json';

const OUTPUTS = {
  js: 'js/src/_builtin_manifest.mjs',
  python: 'python/sel/_builtin_manifest.py',
  php: 'php/src/BuiltinManifest.php',
  cpp: 'cpp/sel_builtin_manifest.hpp',
  lisp: 'lisp/src/builtin-manifest.lisp',
  docs: 'docs/BUILTINS.md',
};

const HEADER = `GENERATED by tools/gen-builtins.mjs from ${SOURCE} — do not edit; edit the manifest and regenerate.`;

// ---------------------------------------------------------------------------
// Validation (spec/builtins.md).

function fail(msg) {
  process.stderr.write(`gen-builtins: ${msg}\n`);
  process.exit(1);
}

const ENTRY_KEYS = new Set(['arity', 'lazy', 'binds', 'signatures', 'spec']);
const ARITY_KEYS = new Set(['min', 'max', 'allowed', 'parity', 'message']);

function load() {
  const doc = JSON.parse(readFileSync(resolve(ROOT, SOURCE), 'utf8'));
  const builtins = doc.builtins;
  if (!builtins || typeof builtins !== 'object') fail('"builtins" must be an object');
  const names = Object.keys(builtins);
  const sorted = [...names].sort();
  for (let i = 0; i < names.length; i++) {
    if (names[i] !== sorted[i]) fail(`entries must be sorted by name: ${names[i]} is out of order`);
  }
  const out = [];
  for (const name of names) {
    const e = builtins[name];
    const where = (k) => `${name}.${k}`;
    if (!/^[A-Z][A-Z0-9_]*$/.test(name)) fail(`${name}: a builtin name is upper-case ASCII`);
    for (const k of Object.keys(e)) if (!ENTRY_KEYS.has(k)) fail(`${where(k)}: unknown key`);
    const a = e.arity;
    if (!a || typeof a !== 'object') fail(`${where('arity')}: required`);
    for (const k of Object.keys(a)) if (!ARITY_KEYS.has(k)) fail(`${where('arity.' + k)}: unknown key`);
    if (!Number.isInteger(a.min) || a.min < 0) fail(`${where('arity.min')}: a non-negative integer`);
    const variadic = a.max === 'variadic';
    if (!variadic && (!Number.isInteger(a.max) || a.max < a.min)) {
      fail(`${where('arity.max')}: an integer >= min, or "variadic"`);
    }
    if (a.allowed !== undefined && a.parity !== undefined) fail(`${where('arity')}: allowed and parity are exclusive`);
    if (a.allowed !== undefined) {
      if (variadic) fail(`${where('arity.allowed')}: needs a numeric max`);
      if (!Array.isArray(a.allowed) || a.allowed.length < 2) fail(`${where('arity.allowed')}: at least two counts`);
      for (let i = 0; i < a.allowed.length; i++) {
        const c = a.allowed[i];
        if (!Number.isInteger(c) || c < a.min || c > a.max) fail(`${where('arity.allowed')}: ${c} is outside min..max`);
        if (i > 0 && c <= a.allowed[i - 1]) fail(`${where('arity.allowed')}: counts ascend, no repeats`);
      }
      if (a.allowed.length === a.max - a.min + 1) fail(`${where('arity.allowed')}: lists every count in the range — drop it`);
    }
    if (a.parity !== undefined && a.parity !== 'odd' && a.parity !== 'even') fail(`${where('arity.parity')}: "odd" or "even"`);
    const hasRule = a.allowed !== undefined || a.parity !== undefined;
    if (hasRule) {
      if (typeof a.message !== 'string' || !a.message.includes('{count}')) {
        fail(`${where('arity.message')}: required with a rule, and must contain {count}`);
      }
    } else if (a.message !== undefined) {
      fail(`${where('arity.message')}: only with allowed or parity`);
    }
    for (const k of ['lazy', 'binds']) {
      if (e[k] !== undefined && e[k] !== true) fail(`${where(k)}: true or absent`);
    }
    if (e.binds && !e.lazy) fail(`${where('binds')}: a binding builtin is lazy`);
    if (!Array.isArray(e.signatures) || e.signatures.length === 0) fail(`${where('signatures')}: at least one form`);
    for (const s of e.signatures) {
      if (typeof s !== 'string' || !s.startsWith(name + '(') || !s.endsWith(')')) {
        fail(`${where('signatures')}: "${s}" is not a ${name}(…) form`);
      }
    }
    if (typeof e.spec !== 'string' || !/^§\d+(\.\d+)*$/.test(e.spec)) fail(`${where('spec')}: "§n.m"`);
    out.push({
      name, min: a.min, max: variadic ? null : a.max,
      allowed: a.allowed ?? null, parity: a.parity ?? null, message: a.message ?? null,
      lazy: !!e.lazy, binds: !!e.binds, signatures: e.signatures, spec: e.spec,
    });
  }
  return out;
}

// ---------------------------------------------------------------------------
// Renderers. Every string literal goes through the host's own escaping.

const jsStr = (s) => JSON.stringify(s);
const pyStr = (s) => "'" + s.replace(/\\/g, '\\\\').replace(/'/g, "\\'") + "'";
const phpStr = (s) => "'" + s.replace(/\\/g, '\\\\').replace(/'/g, "\\'") + "'";
const cppStr = (s) => '"' + s.replace(/\\/g, '\\\\').replace(/"/g, '\\"') + '"';
const lispStr = (s) => '"' + s.replace(/\\/g, '\\\\').replace(/"/g, '\\"') + '"';

function renderJs(entries) {
  const lines = [
    `// ${HEADER}`,
    '//',
    '// One frozen record per builtin: min, max (Infinity when variadic), lazy,',
    '// binds, and the extra arity rule ({ parity, message } or { allowed, message })',
    '// or null. registry.mjs checks every define() against it.',
    '',
    'export const BUILTIN_MANIFEST = Object.freeze({',
  ];
  for (const e of entries) {
    let rule = 'null';
    if (e.parity) rule = `{ parity: ${jsStr(e.parity)}, message: ${jsStr(e.message)} }`;
    else if (e.allowed) rule = `{ allowed: [${e.allowed.join(', ')}], message: ${jsStr(e.message)} }`;
    lines.push(`  ${e.name}: { min: ${e.min}, max: ${e.max === null ? 'Infinity' : e.max}, lazy: ${e.lazy}, binds: ${e.binds}, arity: ${rule} },`);
  }
  lines.push('});', '');
  return lines.join('\n');
}

function renderPython(entries) {
  const lines = [
    `# ${HEADER}`,
    '#',
    '# One tuple per builtin: (min, max, lazy, binds, rule) with max INF when',
    "# variadic and rule None, ('parity', 'odd'|'even', message) or",
    "# ('allowed', (counts...), message). registry.py checks every define() against it.",
    '',
    'INF = float(\'inf\')',
    '',
    'BUILTIN_MANIFEST = {',
  ];
  for (const e of entries) {
    let rule = 'None';
    if (e.parity) rule = `('parity', ${pyStr(e.parity)}, ${pyStr(e.message)})`;
    else if (e.allowed) rule = `('allowed', (${e.allowed.join(', ')}), ${pyStr(e.message)})`;
    lines.push(`    ${pyStr(e.name)}: (${e.min}, ${e.max === null ? 'INF' : e.max}, ${e.lazy ? 'True' : 'False'}, ${e.binds ? 'True' : 'False'}, ${rule}),`);
  }
  lines.push('}', '');
  return lines.join('\n');
}

function renderPhp(entries) {
  const lines = [
    '<?php',
    `// ${HEADER}`,
    '//',
    '// One row per builtin: [min, max, lazy, binds, rule] with max PHP_INT_MAX when',
    "// variadic and rule null, ['parity', 'odd'|'even', message] or",
    "// ['allowed', [counts...], message]. Registry::define checks every definition",
    '// against it.',
    '',
    'declare(strict_types=1);',
    '',
    'namespace Sel;',
    '',
    'final class BuiltinManifest',
    '{',
    '    /** @var array<string, array{0:int,1:int,2:bool,3:bool,4:array<int,mixed>|null}> */',
    '    public const BUILTINS = [',
  ];
  for (const e of entries) {
    let rule = 'null';
    if (e.parity) rule = `['parity', ${phpStr(e.parity)}, ${phpStr(e.message)}]`;
    else if (e.allowed) rule = `['allowed', [${e.allowed.join(', ')}], ${phpStr(e.message)}]`;
    lines.push(`        ${phpStr(e.name)} => [${e.min}, ${e.max === null ? 'PHP_INT_MAX' : e.max}, ${e.lazy}, ${e.binds}, ${rule}],`);
  }
  lines.push('    ];', '}', '');
  return lines.join('\n');
}

function renderCpp(entries) {
  const lines = [
    `// ${HEADER}`,
    '//',
    '// One entry per builtin, sorted by name so lookup can bisect: min, max (-1',
    '// when variadic — the includer maps it to its own sentinel), lazy, binds and',
    '// the extra arity rule as a plain function, or nullptr. sel.cpp checks every',
    '// define() against it.',
    '#pragma once',
    '',
    '#include <string>',
    '',
    'namespace sel_builtin_manifest {',
    '',
    'struct Entry {',
    '  const char* name;',
    '  int min;',
    '  int max;',
    '  bool lazy;',
    '  bool binds;',
    '  std::string (*arity_error)(int);',
    '};',
    '',
  ];
  for (const e of entries) {
    if (!e.parity && !e.allowed) continue;
    const [before, after] = e.message.split('{count}');
    const test = e.parity
      ? `n % 2 ${e.parity === 'odd' ? '== 0' : '!= 0'}`
      : `!(${e.allowed.map((c) => `n == ${c}`).join(' || ')})`;
    lines.push(
      `inline std::string arity_${e.name}(int n) {`,
      `  if (${test}) return ${cppStr(before)} + std::to_string(n) + ${cppStr(after)};`,
      '  return "";',
      '}',
      '',
    );
  }
  lines.push('inline const Entry ENTRIES[] = {');
  for (const e of entries) {
    const rule = e.parity || e.allowed ? `arity_${e.name}` : 'nullptr';
    lines.push(`  {${cppStr(e.name)}, ${e.min}, ${e.max === null ? -1 : e.max}, ${e.lazy}, ${e.binds}, ${rule}},`);
  }
  lines.push('};', '', `inline constexpr int COUNT = ${entries.length};`, '', '}  // namespace sel_builtin_manifest', '');
  return lines.join('\n');
}

function renderLisp(entries) {
  const lines = [
    `;;;; ${HEADER}`,
    ';;;;',
    ';;;; One list per builtin: (name min max lazy binds rule), max :VARIADIC when',
    ';;;; variadic and rule NIL, (:parity :odd|:even message) or',
    ';;;; (:allowed (counts...) message). registry.lisp checks every DEFINE-BUILTIN',
    ';;;; against it.',
    '',
    '(in-package #:sel)',
    '',
    '(setf *builtin-manifest-data*',
    "      '(",
  ];
  for (const e of entries) {
    let rule = 'nil';
    if (e.parity) rule = `(:parity :${e.parity} ${lispStr(e.message)})`;
    else if (e.allowed) rule = `(:allowed (${e.allowed.join(' ')}) ${lispStr(e.message)})`;
    lines.push(`        (${lispStr(e.name)} ${e.min} ${e.max === null ? ':variadic' : e.max} ${e.lazy ? 't' : 'nil'} ${e.binds ? 't' : 'nil'} ${rule})`);
  }
  lines[lines.length - 1] += '))';
  lines.push('');
  return lines.join('\n');
}

function arityText(e) {
  if (e.allowed) return e.allowed.join(' or ');
  const range = e.max === null ? `${e.min}+` : e.min === e.max ? `${e.min}` : `${e.min}–${e.max}`;
  return e.parity ? `${range}, ${e.parity}` : range;
}

function renderDocs(entries) {
  const lines = [
    `<!-- ${HEADER} -->`,
    '# Builtins',
    '',
    'Every SEL builtin, from the authored manifest `spec/builtins.json` (format:',
    '`spec/builtins.md`). *Arguments* is the accepted count; *Evaluates* says',
    'whether the function receives values (strict) or argument nodes (lazy), and',
    'whether it introduces an element binder. The section is where `spec/SPEC.md`',
    'defines the semantics; this table only says what the function table knows.',
    '',
    '| Name | Signature | Arguments | Evaluates | Spec |',
    '|---|---|---|---|---|',
  ];
  for (const e of entries) {
    const sig = e.signatures.map((s) => '`' + s + '`').join('<br>');
    const how = e.binds ? 'lazy, binds' : e.lazy ? 'lazy' : 'strict';
    lines.push(`| \`${e.name}\` | ${sig} | ${arityText(e)} | ${how} | ${e.spec} |`);
  }
  const lazy = entries.filter((e) => e.lazy).length;
  const binds = entries.filter((e) => e.binds).length;
  const rules = entries.filter((e) => e.parity || e.allowed).map((e) => '`' + e.name + '`').join(', ');
  lines.push('', `${entries.length} builtins: ${lazy} lazy, of which ${binds} bind; extra arity rules on ${rules}.`, '');
  return lines.join('\n');
}

// ---------------------------------------------------------------------------

const entries = load();
const rendered = {
  js: renderJs(entries), python: renderPython(entries), php: renderPhp(entries),
  cpp: renderCpp(entries), lisp: renderLisp(entries), docs: renderDocs(entries),
};

if (process.argv.includes('--check')) {
  let stale = 0;
  for (const [host, path] of Object.entries(OUTPUTS)) {
    let current = null;
    try { current = readFileSync(resolve(ROOT, path), 'utf8'); } catch { /* missing */ }
    if (current !== rendered[host]) {
      process.stderr.write(`gen-builtins: ${path} is ${current === null ? 'missing' : 'stale'}\n`);
      stale++;
    }
  }
  if (stale) process.exit(1);
  process.stdout.write(`gen-builtins: ${entries.length} builtins, ${Object.keys(OUTPUTS).length} renderings current\n`);
} else {
  for (const [host, path] of Object.entries(OUTPUTS)) {
    writeFileSync(resolve(ROOT, path), rendered[host]);
    process.stdout.write(`wrote ${path}\n`);
  }
}
